mapper.select:
select distinct SCENARIO_ID, SCENARIO_TYPE
from V_SCENARIO_RULE



            and SCENARIO_ID in

                #{id}



            and SCENARIO_ID = #{scenarioIdList}

select SCENARIO_ID as SCENARIO_SET_CODE, SCENARIO_ID as SCENARIO_CODE, SCENARIO_NAME, SCENARIO_TYPE, CURVE_TYPE, CURVE_CODE, TERM_CODE, TERM_DAYS, SCENARIO_SHIFT_VALUE, SCENARIO_SHIFT_RULE from V_SCENARIO_RULE
and SCENARIO_ID in
#{id}
and SCENARIO_ID = #{scenarioIdList}
order by SCENARIO_ID, CURVE_TYPE, CURVE_CODE, coalesce(TERM_DAYS, 0), TERM_CODE

select SCENARIO_ID as SCENARIO_SET_CODE, SCENARIO_ID as SCENARIO_CODE, SCENARIO_NAME, SCENARIO_TYPE, START_DATE, END_DATE, SCENARIO_NO, SCENARIO_NO as SCENARIO_NUMBER, JUNP_DAY_NO, INCREASE_DAYS, SCENARIO_SHIFT_RULE, CURVE_TYPE as RISKFACTOR_TYPE, CURVE_TYPE, CURVE_CODE, RISKGROUP_ID, TERM_CODE, TERM_DAYS from V_SCENARIO_RULE
and SCENARIO_ID in
#{id}
and SCENARIO_ID = #{scenarioIdList}
order by SCENARIO_ID, CURVE_TYPE, CURVE_CODE, coalesce(TERM_DAYS, 0), TERM_CODE

select SCENARIO_ID as SCENARIO_SET_CODE, SCENARIO_ID as SCENARIO_CODE, SCENARIO_NAME, SCENARIO_TYPE, START_DATE, END_DATE, SCENARIO_NO, JUNP_DAY_NO, INCREASE_DAYS, SCENARIO_SHIFT_RULE, CURVE_TYPE as RISKFACTOR_TYPE, CURVE_TYPE, CURVE_CODE, RISKGROUP_ID, TERM_CODE, TERM_DAYS from V_SCENARIO_RULE
and SCENARIO_ID in
#{id}
and SCENARIO_ID = #{scenarioIdList}
order by SCENARIO_ID, CURVE_TYPE, CURVE_CODE, coalesce(TERM_DAYS, 0), TERM_CODE

select
    CURVE_TYPE,
    CURVE_CODE,
    DATA_DATE,
    TERM_CODE,
    TERM_DAYS,
    RISKFACTOR_VALUE
from V_SCN_MKT_IR_SPOT



            and DATA_DATE between #{startDate} and #{endDate}


            and DATA_DATE = #{startDate}


            and DATA_DATE = #{endDate}




            and CURVE_CODE = #{curveCode}


            and CURVE_CODE in (
                select distinct CURVE_CODE
                from V_SCENARIO_RULE
                where SCENARIO_ID = #{scenarioId}
                  and CURVE_TYPE = 'IR_SPOT'
            )

